<?php
namespace App\Jobs;use App\Contracts\ProtectedMediaStorage;use App\Models\{MediaAsset,MediaVariant};use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Queue\Middleware\WithoutOverlapping;use Illuminate\Support\Str;use RuntimeException;
class GenerateWatermarkedVariant implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=3;public function __construct(public int$assetId){$this->onQueue('media-default');}public function middleware():array{return[(new WithoutOverlapping('watermark-'.$this->assetId))->expireAfter(180)->dontRelease()];}public function handle(ProtectedMediaStorage$storage):void{$asset=MediaAsset::with('group')->findOrFail($this->assetId);if(!$asset->group->watermark_enabled||$asset->variants()->where('variant_type','watermarked')->where('state','ready')->exists())return;$source=$asset->variant('optimized');if(!$source)throw new RuntimeException('Optimized source unavailable.');$stream=$storage->readStream($source->object_key);$image=@imagecreatefromstring(stream_get_contents($stream));fclose($stream);if(!$image)throw new RuntimeException('Watermark source invalid.');$text=trim((string)$asset->group->watermark_text)?:'LensPic';$color=imagecolorallocatealpha($image,255,255,255,40);imagestring($image,5,max(8,imagesx($image)-strlen($text)*10-16),max(8,imagesy($image)-32),$text,$color);ob_start();imagejpeg($image,null,88);$bytes=(string)ob_get_clean();imagedestroy($image);$key=config('media.prefixes.watermarked').'/groups/'.$asset->group_id.'/'.Str::uuid().'.jpg';$storage->put($key,$bytes,'image/jpeg');MediaVariant::create(['media_asset_id'=>$asset->id,'variant_type'=>'watermarked','storage_disk'=>$storage->disk(),'object_key'=>$key,'mime_type'=>'image/jpeg','size_bytes'=>strlen($bytes),'checksum_sha256'=>hash('sha256',$bytes),'state'=>'ready']);}}
